## 1️⃣ `ChatModel.swift`（Domain）

```swift
public struct ChatModel: Identifiable, Codable {
    public var id: String?
    public let senderUID: String
    public let receiverUID: String
    public let text: String
    public let timestamp: Date
    public let imageURLs: [String]?   // ← 新規。複数画像URL
    public var isRead: Bool

    public init(
        id: String? = nil,
        senderUID: String,
        receiverUID: String,
        text: String,
        timestamp: Date,
        imageURLs: [String]? = nil,
        isRead: Bool = false
    ) {
        self.id = id
        self.senderUID = senderUID
        self.receiverUID = receiverUID
        self.text = text
        self.timestamp = timestamp
        self.imageURLs = imageURLs
        self.isRead = isRead
    }

    // MARK: - Backward compatibility
    // 旧フィールド `imageURL: String?` で保存されたメッセージを読み込めるようにする
    enum CodingKeys: String, CodingKey {
        case id, senderUID, receiverUID, text, timestamp, imageURLs, isRead
        case legacyImageURL = "imageURL"
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        self.id          = try c.decodeIfPresent(String.self, forKey: .id)
        self.senderUID   = try c.decode(String.self, forKey: .senderUID)
        self.receiverUID = try c.decode(String.self, forKey: .receiverUID)
        self.text        = try c.decode(String.self, forKey: .text)
        self.timestamp   = try c.decode(Date.self, forKey: .timestamp)
        self.isRead      = try c.decodeIfPresent(Bool.self, forKey: .isRead) ?? false

        if let urls = try c.decodeIfPresent([String].self, forKey: .imageURLs) {
            self.imageURLs = urls
        } else if let legacy = try c.decodeIfPresent(String.self, forKey: .legacyImageURL) {
            self.imageURLs = [legacy]
        } else {
            self.imageURLs = nil
        }
    }
    // encode はデフォルト合成だと legacyImageURL も書こうとするので明示
    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        try c.encodeIfPresent(id, forKey: .id)
        try c.encode(senderUID, forKey: .senderUID)
        try c.encode(receiverUID, forKey: .receiverUID)
        try c.encode(text, forKey: .text)
        try c.encode(timestamp, forKey: .timestamp)
        try c.encodeIfPresent(imageURLs, forKey: .imageURLs)
        try c.encode(isRead, forKey: .isRead)
    }
}
```

**ポイント**
- 新規メッセージは `imageURLs` のみで保存される
- 旧メッセージ（`imageURL: "..."`）は読み込み時に `[legacy]` に変換される
- 表示側は `imageURLs ?? []` で吸収できる

> 既存の表示側（吹き出し UI で imageURL を読んでる箇所）も `imageURLs?.first` に置き換える必要がある。grep で `imageURL` を全件確認して直すこと。

