## 3️⃣ `FirebaseClient.swift`（Data）

```swift
public static func uploadChatImages(
    _ images: [UIImage],
    messageID: String
) async throws -> [String] {
    // インデックス付き並列アップロード。順序は元の配列順を保つ
    try await withThrowingTaskGroup(of: (Int, String).self) { group in
        for (index, image) in images.enumerated() {
            group.addTask {
                let url = try await uploadSingle(image, messageID: messageID, index: index)
                return (index, url)
            }
        }
        var collected: [(Int, String)] = []
        for try await pair in group { collected.append(pair) }
        return collected.sorted { $0.0 < $1.0 }.map { $0.1 }
    }
}

private static func uploadSingle(
    _ image: UIImage,
    messageID: String,
    index: Int
) async throws -> String {
    let storageRef = Storage.storage().reference()
        .child("chat_images/\(messageID)_\(index).jpg")
    guard let data = image.jpegData(compressionQuality: 0.8) else {
        throw NSError(domain: "FirebaseClient", code: -1)
    }
    return try await withCheckedThrowingContinuation { cont in
        storageRef.putData(data, metadata: nil) { _, error in
            if let error = error { cont.resume(throwing: error); return }
            storageRef.downloadURL { url, error in
                if let error = error { cont.resume(throwing: error); return }
                cont.resume(returning: url?.absoluteString ?? "")
            }
        }
    }
}
```

**ポイント**
- パスは `chat_images/{messageID}_{index}.jpg`（explorer 提案そのまま）
- 並列で投げて順序を維持
- 既存 `uploadChatImage(_:messageID:)` は当面残す（他の呼び出し元があるかも）

