## 6️⃣ `ChatViewModel.swift`

```swift
func send(_ event: ChatViewEvent) {
    switch event {
    // ...
    case .onAddImage(let image):
        viewState.selectedImages.append(image)

    case .onRemoveImage(let index):
        guard viewState.selectedImages.indices.contains(index) else { return }
        viewState.selectedImages.remove(at: index)

    case .onClearImages:
        viewState.selectedImages.removeAll()

    case .onSend:
        handleSend()
    }
}

private func handleSend() {
    let text = viewState.text
    let images = viewState.selectedImages
    guard !text.isEmpty || !images.isEmpty else { return }

    let messageID = UUID().uuidString

    if images.isEmpty {
        // テキストのみ
        Task {
            let message = ChatModel(
                id: messageID,
                senderUID: context.currentUID,
                receiverUID: viewState.receiverUID,
                text: text,
                timestamp: Date(),
                imageURLs: nil
            )
            try await context.chatRepository.sendMessage(
                uid: viewState.receiverUID, message: message
            )
            await MainActor.run {
                viewState.text = ""
            }
        }
    } else {
        // テキスト + 画像複数
        viewState.isUploading = true
        Task {
            defer { Task { @MainActor in viewState.isUploading = false } }
            let urls = try await context.storageRepository
                .uploadChatImages(images, messageID: messageID)
            let message = ChatModel(
                id: messageID,
                senderUID: context.currentUID,
                receiverUID: viewState.receiverUID,
                text: text,
                timestamp: Date(),
                imageURLs: urls
            )
            try await context.chatRepository.sendMessage(
                uid: viewState.receiverUID, message: message
            )
            await MainActor.run {
                viewState.text = ""
                viewState.selectedImages.removeAll()
            }
        }
    }
}
```

**ポイント**
- `canSend = !text.isEmpty || !selectedImages.isEmpty` を上で判定
- 送信成功で text と selectedImages を両方クリア
- 失敗時のロールバックは現状の単数版と同等で OK（必要ならエラー Toast を別タスクで足す）

