## 8️⃣ `ChatInputBar.swift`

```swift
struct ChatInputBar: View {
    @Binding var text: String
    @Binding var selectedPhotoItems: [PhotosPickerItem]
    let selectedImages: [UIImage]
    let isUploading: Bool
    let onAddImage: (UIImage) -> Void
    let onRemoveImage: (Int) -> Void
    let onSend: () -> Void

    private var canSend: Bool {
        !text.isEmpty || !selectedImages.isEmpty
    }

    var body: some View {
        VStack(spacing: 8) {
            // 1) サムネ Row（0枚なら非表示）
            if !selectedImages.isEmpty {
                ChatImageThumbnailRow(
                    images: selectedImages,
                    onRemove: onRemoveImage
                )
            }

            // 2) TextField + ボタン
            HStack(spacing: 12) {
                PhotosPicker(
                    selection: $selectedPhotoItems,
                    maxSelectionCount: 10,
                    matching: .images
                ) {
                    Image(systemName: "photo.on.rectangle")
                        .font(.system(size: 22))
                        .foregroundStyle(.secondary)
                }

                TextField("メッセージ", text: $text, axis: .vertical)
                    .textFieldStyle(.plain)
                    .lineLimit(1...5)

                Button(action: onSend) {
                    Image(systemName: "arrow.up.circle.fill")
                        .font(.system(size: 28))
                        .foregroundStyle(canSend ? Color.accentColor : Color.secondary)
                }
                .disabled(!canSend || isUploading)
            }
        }
        .padding(.horizontal, 12)
        .padding(.vertical, 8)
        // 既存の Liquid Glass / 背景 modifier はそのまま維持
        .onChange(of: selectedPhotoItems) { _, newItems in
            // PhotosPicker の選択結果を 1枚ずつ UIImage 化して .onAddImage で流す
            Task {
                for item in newItems {
                    if let data = try? await item.loadTransferable(type: Data.self),
                       let image = UIImage(data: data) {
                        await MainActor.run {
                            onAddImage(image)
                        }
                    }
                }
                // 取り込んだら picker の selection はクリア（次回選択を素直に受けるため）
                await MainActor.run {
                    selectedPhotoItems.removeAll()
                }
            }
        }
    }
}
```

**ポイント**
- `VStack(spacing: 8)` でサムネ Row を上に、入力行を下に
- 0枚は `if !selectedImages.isEmpty` で完全に消す（高さも消える）
- PhotosPicker の `maxSelectionCount: 10` をハードコード（将来定数化したければ AppConstants 行きで OK）
- onChange で newItems を回して loadTransferable → onAddImage に流す
- **picker selection を取り込み後にクリアする**のが地味に重要。これやらないと既出選択が次回に持ち越されて二重追加になる

